import csv
import io
import re
import collections
import typing


def parse_csv(raw_csv: str):
    expected_width = 9

    def is_blank(row):
        return not row or all(cell == "" for cell in row)

    def clean_header_value(value):
        return value.lstrip("\ufeff").strip()

    def normalized_word(value):
        return re.sub(r"[^a-z0-9]+", "", value.lower())

    known_header_words = {
        "date", "time", "qty", "quantity", "productid", "product",
        "price", "producttype", "description", "productdescription",
        "url", "comments", "comment"
    }

    def looks_like_date(value):
        return bool(re.match(r"^\s*\d{1,4}[/-]\d{1,2}[/-]\d{1,4}\s*$", value))

    def header_score(row):
        if not row:
            return -1
        score = 0
        words = [normalized_word(cell) for cell in row]
        for word in words:
            if word in known_header_words:
                score += 2
        if words and words[0] == "date":
            score += 5
        if words and any(looks_like_date(cell) for cell in row[:1]):
            score -= 5
        if len(row) == expected_width:
            score += 1
        return score

    def normalize_row(row):
        values = list(row)
        if len(values) < expected_width:
            values.extend([""] * (expected_width - len(values)))
        elif len(values) > expected_width:
            values = values[:expected_width - 1] + [",".join(values[expected_width - 1:])]
        return values

    def is_metadata_row(row):
        if not row:
            return False
        first = row[0].strip()
        return bool(re.match(r"^(?:export|section|source)\s*:", first, re.I))

    try:
        reader = csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            strict=False
        )
        records = list(reader)
    except csv.Error:
        records = []
        for line in raw_csv.splitlines():
            try:
                records.append(next(csv.reader(
                    [line],
                    delimiter=",",
                    quotechar='"',
                    doublequote=True,
                    strict=False
                )))
            except (csv.Error, StopIteration):
                records.append([line])

    records = [row for row in records if not is_blank(row)]

    candidates = []
    for index, row in enumerate(records):
        score = header_score(row)
        if score >= 5 and len(row) >= 6:
            candidates.append((index, score, row))

    header_indices = set()
    columns = None

    if candidates:
        best_score = max(item[1] for item in candidates)
        best = next(item for item in candidates if item[1] == best_score)
        best_index = best[0]
        best_row = normalize_row(best[2])
        header_indices.add(best_index)

        adjacent = []
        for index, score, row in candidates:
            if index != best_index and abs(index - best_index) == 1:
                adjacent.append((index, score, row))

        if adjacent:
            other_index, other_score, other_row = adjacent[0]
            if other_score >= 5:
                first = normalize_row(best[2])
                second = normalize_row(other_row)
                combined = []
                for left, right in zip(first, second):
                    left_clean = clean_header_value(left)
                    right_clean = clean_header_value(right)
                    if left_clean and right_clean and left_clean.lower() != right_clean.lower():
                        combined.append(left_clean + " " + right_clean)
                    else:
                        combined.append(left_clean or right_clean)
                columns = combined
                header_indices.add(other_index)

        if columns is None:
            columns = [clean_header_value(value) for value in best_row]

        for index, score, row in candidates:
            if score >= best_score - 1 and len(row) == expected_width:
                first = normalized_word(row[0]) if row else ""
                if first == "date":
                    header_indices.add(index)
    else:
        columns = ["column_" + str(index + 1) for index in range(expected_width)]

    rows = []
    data_seen = False

    for index, record in enumerate(records):
        if index in header_indices:
            continue
        if is_metadata_row(record):
            continue

        if len(record) >= expected_width:
            data_seen = True
        elif not data_seen:
            continue

        normalized = normalize_row(record)
        if normalized_word(normalized[0]) == "date" and header_score(record) >= 5:
            continue
        rows.append(normalized)

    return {"columns": columns, "rows": rows}
